// Простой скетч для мигания 6 светодиодами по очереди

void setup() {
  // Настраиваем пины 2, 3, 4, 5, 6, 7 как выходы (OUTPUT)
  for (int i = 2; i <= 7; i++) {
    pinMode(i, OUTPUT);
  }
}

void loop() {
  // Пробегаемся по всем пинам от 2 до 7
  for (int i = 2; i <= 7; i++) {
    digitalWrite(i, HIGH); // Включаем светодиод
    delay(200);            // Ждем 0.2 секунды
    digitalWrite(i, LOW);  // Выключаем светодиод
  }

  // Теперь пробегаемся в обратном порядке от 7 до 2
  for (int i = 7; i >= 2; i--) {
    digitalWrite(i, HIGH);
    delay(200);
    digitalWrite(i, LOW);
  }
}
